import{_ as a,c as e,o as n,aa as d}from"./chunks/framework.tkU0Ryf1.js";const u=JSON.parse('{"title":"跨平台应用与状态区图标设计规范：Apple、Android、Windows 与多尺寸派生","description":"梳理应用图标、界面图标与状态区图标的差异，说明主流平台的交付规则，以及从设计母版派生多尺寸资源的方法。","frontmatter":{"title":"跨平台应用与状态区图标设计规范：Apple、Android、Windows 与多尺寸派生","description":"梳理应用图标、界面图标与状态区图标的差异，说明主流平台的交付规则，以及从设计母版派生多尺寸资源的方法。","date":"2026-07-01T20:30:00.000Z","tags":["UI设计","AppIcon","iOS","Android","macOS","Windows"]},"headers":[],"relativePath":"posts/应用图标设计规范调研.md","filePath":"posts/应用图标设计规范调研.md","lastUpdated":1787021012000}'),i={name:"posts/应用图标设计规范调研.md"};function s(p,t,o,l,r,c){return n(),e("div",null,[...t[0]||(t[0]=[d(`<p>跨平台图标要统一的是识别核心，不是同一张图片。开始设计前，先回答三个问题：</p><ol><li>这是应用图标、界面图标，还是状态区图标？</li><li>最终轮廓由系统蒙版、商店处理，还是图片本身负责？</li><li>图标最小会显示到多大，系统是否会重新着色或添加底板？</li></ol><p>这三个问题决定了画布、透明度、圆角和小尺寸版本应该怎么做。</p><h2 id="一、先区分图标的用途" tabindex="-1">一、先区分图标的用途 <a class="header-anchor" href="#一、先区分图标的用途" aria-label="Permalink to &quot;一、先区分图标的用途&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>常见位置</th><th>设计重点</th></tr></thead><tbody><tr><td>应用图标</td><td>桌面、Dock、启动器、商店</td><td>品牌识别、平台容器、外观适配</td></tr><tr><td>界面图标</td><td>按钮、导航、工具栏、设置项</td><td>操作语义、线宽和文字对齐</td></tr><tr><td>状态区图标</td><td>macOS 菜单栏、Windows 系统托盘</td><td>极小尺寸识别、平台原生感</td></tr><tr><td>Web 图标</td><td>浏览器标签、PWA、书签</td><td>16px 可读性和浏览器兼容</td></tr></tbody></table><p>应用图标与状态区图标可以共享品牌符号，但不应默认共用同一张渲染图。应用图标需要表现品牌，状态区图标首先要适应系统环境。</p><h2 id="二、apple、android-与-windows-的交付差异" tabindex="-1">二、Apple、Android 与 Windows 的交付差异 <a class="header-anchor" href="#二、apple、android-与-windows-的交付差异" aria-label="Permalink to &quot;二、Apple、Android 与 Windows 的交付差异&quot;">​</a></h2><h3 id="_2-1-apple" tabindex="-1">2.1 Apple <a class="header-anchor" href="#_2-1-apple" aria-label="Permalink to &quot;2.1 Apple&quot;">​</a></h3><p>当前 Apple 图标工作流使用 1024 × 1024 px 方形布局。iOS、iPadOS 和新版 macOS 会对图层应用圆角和系统材质效果，因此应交付未蒙版图层，不要提前画系统圆角或贴边阴影。</p><p>Apple 图标需要检查默认、深色和单色外观。背景、主体、高光和阴影最好分层保存，再通过 Icon Composer 或 Xcode 预览不同平台、尺寸和外观。</p><p>传统 <code>.icns</code> 和现有打包框架不一定采用最新图标管线。DMG、Finder 和旧系统中的最终轮廓仍需实机确认，不能仅凭设计规范推断。</p><h3 id="_2-2-android" tabindex="-1">2.2 Android <a class="header-anchor" href="#_2-2-android" aria-label="Permalink to &quot;2.2 Android&quot;">​</a></h3><p>Android Adaptive Icon 由三个部分组成：</p><table tabindex="0"><thead><tr><th>图层</th><th>作用</th></tr></thead><tbody><tr><td>Background</td><td>铺满画布的背景</td></tr><tr><td>Foreground</td><td>主体，可参与启动器视差和动画</td></tr><tr><td>Monochrome</td><td>Android 13+ 主题图标使用的单色图层</td></tr></tbody></table><p>各图层使用 108 × 108 dp 画布，关键内容放在中心安全区。启动器可能裁成圆形、圆角方形或水滴形，因此不能预先画死外框。</p><p>Google Play 的 512 × 512 px 商店图标是独立资源，不等同于启动器图标。商店会处理圆角和阴影，上传前不要预裁圆角。</p><h3 id="_2-3-windows" tabindex="-1">2.3 Windows <a class="header-anchor" href="#_2-3-windows" aria-label="Permalink to &quot;2.3 Windows&quot;">​</a></h3><p>Windows 不会把所有应用图标统一裁成同一种容器。透明轮廓通常是合理选择，也可以按品牌需要使用底板。</p><p>Windows 会优先寻找与显示尺寸匹配的图片，找不到时才选择更大的版本缩小。Win32 的 ICO 至少应包含 16、24、32、48 和 256 px，避免只放一张大图交给系统缩放。</p><p>设计时先在 48 × 48 网格建立清楚的轮廓，再针对小尺寸减少转角和内部细节。透明图标需要分别检查浅色、深色任务栏和桌面壁纸。</p><h2 id="三、macos-菜单栏与-windows-托盘" tabindex="-1">三、macOS 菜单栏与 Windows 托盘 <a class="header-anchor" href="#三、macos-菜单栏与-windows-托盘" aria-label="Permalink to &quot;三、macOS 菜单栏与 Windows 托盘&quot;">​</a></h2><p>状态区图标长期占用系统共享空间，尺寸也远小于应用图标。两端的视觉逻辑并不相同。</p><table tabindex="0"><thead><tr><th>维度</th><th>macOS 菜单栏</th><th>Windows 系统托盘</th></tr></thead><tbody><tr><td>色彩</td><td>单色，由系统着色</td><td>可以保留品牌色</td></tr><tr><td>背景</td><td>透明</td><td>通常透明</td></tr><tr><td>识别方式</td><td>轮廓和负空间</td><td>轮廓、颜色和主体关系</td></tr><tr><td>主题适配</td><td>模板机制自动适配</td><td>需要检查不同任务栏背景</td></tr><tr><td>应用图标容器</td><td>删除</td><td>删除</td></tr></tbody></table><p>macOS 使用透明的模板图标。系统负责浅色、深色、选中和辅助功能外观，因此图形不应依赖渐变、材质或品牌色，并要与附近系统图标保持相近的视觉重量。</p><p>Windows 托盘支持带 Alpha 的彩色资源。它可以继承应用图标的主体和颜色，但需要移除大面积背景、外层容器以及小尺寸下无法辨认的细节。至少检查 16、20、24 和 32 px。</p><h3 id="clipclop-的处理" tabindex="-1">ClipClop 的处理 <a class="header-anchor" href="#clipclop-的处理" aria-label="Permalink to &quot;ClipClop 的处理&quot;">​</a></h3><p>ClipClop 的应用图标由牛、马和剪贴板组成。Windows 托盘保留彩色牛马，移除白色背景和剪贴板；macOS 菜单栏进一步简化为单色蹄印，再交给系统着色。</p><p>三个版本共享牛马这一识别来源，但没有共用同一张图片。这比强行统一颜色和构图更符合各自平台。</p><h2 id="四、从母版派生不同尺寸" tabindex="-1">四、从母版派生不同尺寸 <a class="header-anchor" href="#四、从母版派生不同尺寸" aria-label="Permalink to &quot;四、从母版派生不同尺寸&quot;">​</a></h2><p>一张 1024 px 图片可以批量缩放，却不一定能在 16px 下保持清楚。完整的派生过程是：设计母版 → 平台构图 → 光学版本 → 最终文件。</p><h3 id="_4-1-母版保存什么" tabindex="-1">4.1 母版保存什么 <a class="header-anchor" href="#_4-1-母版保存什么" aria-label="Permalink to &quot;4.1 母版保存什么&quot;">​</a></h3><p>母版不是一张大 PNG，而是可编辑的设计来源，包括：</p><ul><li>基础构图网格和主体安全区。</li><li>品牌符号、颜色及主体关系。</li><li>背景、主体、阴影和高光等独立图层。</li><li>彩色、单色以及平台容器的处理方式。</li><li>哪些特征必须保留，哪些细节可以删除。</li></ul><p>不同尺寸必须保持核心轮廓、主体数量与关系、品牌特征和基本视觉重心。主体占比、内部间距、描边粗细、局部比例、阴影和装饰细节可以调整。</p><h3 id="_4-2-先找视觉失效点" tabindex="-1">4.2 先找视觉失效点 <a class="header-anchor" href="#_4-2-先找视觉失效点" aria-label="Permalink to &quot;4.2 先找视觉失效点&quot;">​</a></h3><p>不要先为每个尺寸制作一份设计稿。先从母版导出全部目标尺寸，以 100% 实际大小检查，再标记图形开始模糊、粘连或失衡的位置。只有发生明显失效时，才建立新的光学版本。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设计母版</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>导出目标尺寸</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>检查轮廓、间隙和重心</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>在失效点建立光学版本</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>重新生成对应尺寸</span></span></code></pre></div><p>例如，128px 以上表现正常，48px 开始丢失纹理，24px 主体开始粘连，可以把资源分为 Large、Medium 和 Small；如果所有尺寸都清楚，就不需要为了形式增加版本。</p><h3 id="_4-3-建立光学版本" tabindex="-1">4.3 建立光学版本 <a class="header-anchor" href="#_4-3-建立光学版本" aria-label="Permalink to &quot;4.3 建立光学版本&quot;">​</a></h3><p>可以从三档开始：</p><table tabindex="0"><thead><tr><th>档位</th><th>典型尺寸</th><th>处理方式</th></tr></thead><tbody><tr><td>Large</td><td>256–1024 px</td><td>保留完整构图、材质和层次</td></tr><tr><td>Medium</td><td>48–128 px</td><td>减少纹理和阴影，强化轮廓与间距</td></tr><tr><td>Small</td><td>16–32 px</td><td>保留识别核心，扩大负空间和对比度</td></tr></tbody></table><p>三档不是硬性标准。简单图标可能只需要两档；如果 16px 与 24px 的表现差异很大，可以增加 Tiny 版本。</p><p>缩小时按下面的顺序处理：</p><ol><li>删除无法辨认的纹理和高光。</li><li>缩小或删除模糊阴影。</li><li>加宽过细的轮廓和关键空隙。</li><li>拉开相邻主体，防止粘连。</li><li>调整局部比例和视觉中心。</li></ol><p>同样的画布占比不代表同样的视觉重量。圆形通常需要略微放大，细长图形需要更多方向性空间，不对称图形可以偏离数学中心。阴影不参与主体居中的计算。</p><h3 id="_4-4-将尺寸映射到正确的源版本" tabindex="-1">4.4 将尺寸映射到正确的源版本 <a class="header-anchor" href="#_4-4-将尺寸映射到正确的源版本" aria-label="Permalink to &quot;4.4 将尺寸映射到正确的源版本&quot;">​</a></h3><p>生成脚本应明确每个尺寸使用哪个光学源，而不是始终缩放最大图。例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>16、20、24、32px  ← Small</span></span>
<span class="line"><span>48、64、96px      ← Medium</span></span>
<span class="line"><span>128px 及以上      ← Large</span></span></code></pre></div><p>映射边界来自实际失效点，可以随图标复杂度调整。设计者只维护必要的源版本，工具负责生成最终尺寸。</p><h2 id="五、源文件、导出与验收" tabindex="-1">五、源文件、导出与验收 <a class="header-anchor" href="#五、源文件、导出与验收" aria-label="Permalink to &quot;五、源文件、导出与验收&quot;">​</a></h2><p>源文件保存设计意图，发布文件由脚本生成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IconSystem/</span></span>
<span class="line"><span>├── identity/          # 品牌符号、颜色和轮廓</span></span>
<span class="line"><span>├── app/</span></span>
<span class="line"><span>│   ├── apple/</span></span>
<span class="line"><span>│   ├── android/</span></span>
<span class="line"><span>│   └── windows/</span></span>
<span class="line"><span>├── status/</span></span>
<span class="line"><span>│   ├── macos-template.svg</span></span>
<span class="line"><span>│   └── windows-color.png</span></span>
<span class="line"><span>├── web/</span></span>
<span class="line"><span>└── generated/         # PNG、ICO、ICNS 等派生文件</span></span></code></pre></div><p>脚本适合处理尺寸、格式、ICO/ICNS 合成、文件检查和预览图生成。主体是否清楚、哪些细节应该删除，仍需人工判断。</p><h3 id="最小验收范围" tabindex="-1">最小验收范围 <a class="header-anchor" href="#最小验收范围" aria-label="Permalink to &quot;最小验收范围&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>检查内容</th></tr></thead><tbody><tr><td>尺寸</td><td>16、20、24、32、48、128、512 px</td></tr><tr><td>背景</td><td>浅色、深色、壁纸和系统强调色</td></tr><tr><td>位置</td><td>Dock、Finder、桌面、任务栏、托盘和安装器</td></tr><tr><td>缩放</td><td>Retina 1x/2x，Windows 100%–200%</td></tr><tr><td>外观</td><td>彩色、单色、模板着色和高对比度</td></tr><tr><td>蒙版</td><td>Apple 模板和 Android 常见启动器形状</td></tr></tbody></table><p>以 100% 实际尺寸判断可读性。放大图只用于检查边缘和 Alpha。</p><h2 id="六、常见问题" tabindex="-1">六、常见问题 <a class="header-anchor" href="#六、常见问题" aria-label="Permalink to &quot;六、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原因</th><th>表现</th><th>修正</th></tr></thead><tbody><tr><td>预先画了系统圆角</td><td>出现双重圆角或脏边</td><td>删除预制蒙版</td></tr><tr><td>不支持透明的资源使用 Alpha</td><td>出现黑底或被商店拒绝</td><td>按交付规范决定透明度</td></tr><tr><td>Windows 图标带不必要底板</td><td>任务栏或托盘出现方块</td><td>提供透明的 unplated 资源</td></tr><tr><td>阴影贴近画布边缘</td><td>深色背景出现黑线</td><td>收回阴影或交给系统处理</td></tr><tr><td>主体超出安全区</td><td>Android 启动器裁掉内容</td><td>缩回关键主体</td></tr><tr><td>只从大图缩放</td><td>小尺寸模糊、间隙消失</td><td>制作小尺寸光学版本</td></tr><tr><td>AI 图片直接交付</td><td>出现伪圆角、噪点和错误 Alpha</td><td>拆层并重建边缘</td></tr></tbody></table><h2 id="七、ai-只适合生成初稿" tabindex="-1">七、AI 只适合生成初稿 <a class="header-anchor" href="#七、ai-只适合生成初稿" aria-label="Permalink to &quot;七、AI 只适合生成初稿&quot;">​</a></h2><p>使用 AI 探索图标方向时，应明确要求方形画布、单一主体、无文字和清楚的小尺寸轮廓。但提示词必须服从目标平台：Apple 或 Google Play 可以要求背景铺满；Windows 透明图标和状态区图标不能照搬这个要求。</p><p>AI 输出不能直接交付。至少要清理边缘和 Alpha、拆分主体与背景，并在实际尺寸下重新检查。</p><h2 id="八、发布前检查清单" tabindex="-1">八、发布前检查清单 <a class="header-anchor" href="#八、发布前检查清单" aria-label="Permalink to &quot;八、发布前检查清单&quot;">​</a></h2><ul><li>已确认图标用途和外轮廓由谁负责。</li><li>应用、状态区和商店资源分别制作。</li><li>Apple、Android 与 Windows 使用各自的交付规则。</li><li>源文件可编辑，PNG、ICO、ICNS 可以重新生成。</li><li>小尺寸版本保留轮廓、主体关系和关键负空间。</li><li>已在浅色、深色和真实系统位置检查。</li><li>没有黑框、重复圆角、贴边阴影或无意义底板。</li><li>没有依赖一张大图生成全部尺寸。</li></ul><p>跨平台图标不是把一张图导出成不同尺寸，而是让同一个识别核心在不同环境中保持可辨认。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>Apple Human Interface Guidelines - App icons: <a href="https://developer.apple.com/design/human-interface-guidelines/app-icons" target="_blank" rel="noreferrer">https://developer.apple.com/design/human-interface-guidelines/app-icons</a></li><li>Apple Design Resources: <a href="https://developer.apple.com/design/resources/" target="_blank" rel="noreferrer">https://developer.apple.com/design/resources/</a></li><li>Apple - Icon Composer: <a href="https://developer.apple.com/icon-composer/" target="_blank" rel="noreferrer">https://developer.apple.com/icon-composer/</a></li><li>Apple Human Interface Guidelines - SF Symbols: <a href="https://developer.apple.com/design/human-interface-guidelines/sf-symbols" target="_blank" rel="noreferrer">https://developer.apple.com/design/human-interface-guidelines/sf-symbols</a></li><li>Android Developers - Adaptive icons: <a href="https://developer.android.com/develop/ui/views/launch/icon_design_adaptive" target="_blank" rel="noreferrer">https://developer.android.com/develop/ui/views/launch/icon_design_adaptive</a></li><li>Google Play - Icon design specifications: <a href="https://developer.android.com/google-play/resources/icon-design-specifications" target="_blank" rel="noreferrer">https://developer.android.com/google-play/resources/icon-design-specifications</a></li><li>Google Developers - Material Symbols: <a href="https://developers.google.com/fonts/docs/material_symbols" target="_blank" rel="noreferrer">https://developers.google.com/fonts/docs/material_symbols</a></li><li>Microsoft - Design guidelines for Windows app icons: <a href="https://learn.microsoft.com/windows/apps/design/iconography/app-icon-design" target="_blank" rel="noreferrer">https://learn.microsoft.com/windows/apps/design/iconography/app-icon-design</a></li><li>Microsoft - Construct your Windows app&#39;s icon: <a href="https://learn.microsoft.com/windows/apps/design/iconography/app-icon-construction" target="_blank" rel="noreferrer">https://learn.microsoft.com/windows/apps/design/iconography/app-icon-construction</a></li><li>Microsoft - Notification Area: <a href="https://learn.microsoft.com/windows/win32/uxguide/winenv-notification" target="_blank" rel="noreferrer">https://learn.microsoft.com/windows/win32/uxguide/winenv-notification</a></li><li>IBM Design Language - UI icons: <a href="https://www.ibm.com/design/language/iconography/ui-icons/design/" target="_blank" rel="noreferrer">https://www.ibm.com/design/language/iconography/ui-icons/design/</a></li></ul>`,66)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
